import csv
import io
import re
from typing import List, Dict, Any

def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    text = raw_csv.lstrip("\ufeff")

    def normalize_newlines(s: str) -> str:
        return s.replace("\r\n", "\n").replace("\r", "\n")

    text = normalize_newlines(text)

    def parse_with_csv(s: str):
        reader = csv.reader(io.StringIO(s), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
        return [row for row in reader]

    rows = []
    try:
        rows = parse_with_csv(text)
    except Exception:
        lines = text.split("\n")
        fixed = []
        buf = ""
        in_quotes = False
        for line in lines:
            if buf:
                buf += "\n" + line
            else:
                buf = line
            cnt = 0
            i = 0
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        i += 2
                        continue
                    cnt += 1
                i += 1
            if cnt % 2 == 1:
                in_quotes = not in_quotes
            if not in_quotes:
                fixed.append(buf)
                buf = ""
        if buf:
            fixed.append(buf)
        try:
            rows = parse_with_csv("\n".join(fixed))
        except Exception:
            rows = [r.split(",") for r in fixed if r != ""]

    if not rows:
        return {"columns": [], "rows": []}

    header = rows[0]
    data_rows = rows[1:]

    expected_width = len(header)
    cleaned_rows = []
    for row in data_rows:
        if len(row) < expected_width:
            row = row + [""] * (expected_width - len(row))
        elif len(row) > expected_width:
            row = row[:expected_width - 1] + [",".join(row[expected_width - 1:])]
        cleaned_rows.append([str(v) for v in row])

    return {"columns": [str(c) for c in header], "rows": cleaned_rows}
